-					t2 = &a2->type;
-					l = exp_fix_scale(sql, t1, l, 0, 0);
-					r = exp_fix_scale(sql, t2, r, 0, 0);
-				} else if (f->func->fix_scale == SCALE_DIV) {
-					l = exp_scale_algebra(sql, f, rel, l, r);
-					if (!l)
-						return NULL;
